<?php namespace App\Services; use App\Models\Place; class ItineraryPlannerService { public function preview(array $data):array { $lat=(float)$data['start_latitude'];$lng=(float)$data['start_longitude'];$time=strtotime($data['start_time']);$end=strtotime($data['end_time']);$stops=[];$skipped=[];$total=0; foreach(Place::whereIn('id',$data['place_ids'])->active()->get() as $place){$km=$this->distance($lat,$lng,$place->latitude,$place->longitude);$travel=(int)ceil($km/35*60);$arrival=$time+$travel*60;$open=strtotime(date('Y-m-d').' '.$place->opening_time);$close=strtotime(date('Y-m-d').' '.$place->closing_time);if($arrival<$open)$arrival=$open;if($arrival+$place->visit_duration_minutes*60>$close||$arrival+$place->visit_duration_minutes*60>$end){$skipped[]=['place'=>$place->name,'reason'=>'Outside opening hours or selected day end'];continue;}$stops[]=['place'=>$place,'arrival_time'=>date('H:i',$arrival),'departure_time'=>date('H:i',$arrival+$place->visit_duration_minutes*60),'distance_km'=>round($km,2),'travel_minutes'=>$travel];$time=$arrival+$place->visit_duration_minutes*60;$lat=$place->latitude;$lng=$place->longitude;$total+=$km;}return ['stops'=>$stops,'skipped'=>$skipped,'total_distance'=>round($total,2),'total_travel_minutes'=>array_sum(array_column($stops,'travel_minutes'))];} private function distance($a,$b,$c,$d):float{$r=6371;$x=deg2rad($c-$a);$y=deg2rad($d-$b);$z=sin($x/2)**2+cos(deg2rad($a))*cos(deg2rad($c))*sin($y/2)**2;return $r*2*atan2(sqrt($z),sqrt(1-$z));} }
